data class EnrollmentIconData(
    val color: Int,
    val imageResource: Int
)

sealed class EnrollmentIconItem {
    data class Icon(val data: EnrollmentIconData) : EnrollmentIconItem()
    data class Remaining(val count: Int) : EnrollmentIconItem()
}

fun List<Program>.getEnrollmentIconsData(
    context: Context,
    currentProgram: String?
): List<EnrollmentIconItem> {
    val listSize = this.size
    var programCount = 0
    val resourceManager = ResourceManager(context)

    return buildList {
        run outer@{
            filter { it.uid() != currentProgram }
                .forEach { program ->
                    val color = ColorUtils.getColorFrom(
                        program.style().color(),
                        ColorUtils.getPrimaryColor(
                            context,
                            ColorUtils.ColorType.PRIMARY
                        )
                    )
                    programCount++
                    if (programCount >= ENROLLMENT_ICONS_TO_SHOW &&
                        listSize > ENROLLMENT_ICONS_TO_SHOW
                    ) {
                        add(EnrollmentIconItem.Remaining(getOtherEnrollmentsForTei(listSize)))
                        return@outer
                    } else {
                        val imageResource = resourceManager.getObjectStyleDrawableResource(
                            program.style().icon(),
                            R.drawable.ic_default_icon
                        )
                        add(
                            EnrollmentIconItem.Icon(
                                EnrollmentIconData(
                                    color = color,
                                    imageResource = imageResource
                                )
                            )
                        )
                    }
                }
        }
    }
}

fun List<Program>.addEnrollmentIcons(
    context: Context,
    parent: ComposeView,
    currentProgram: String?
) {
    val enrollmentIconItems = getEnrollmentIconsData(context, currentProgram)
    parent.apply {
        setContent {
            MdcTheme {
                Row(
                    horizontalArrangement = spacedBy(Dp(4f)),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    enrollmentIconItems.forEach { enrollmentIconItem ->
                        when (enrollmentIconItem) {
                            is EnrollmentIconItem.Icon -> MetadataIcon(
                                metadataIconData = MetadataIconData(
                                    programColor = enrollmentIconItem.data.color,
                                    iconResource = enrollmentIconItem.data.imageResource,
                                    sizeInDp = 24
                                )
                            )
                            is EnrollmentIconItem.Remaining -> SquareWithNumber(enrollmentIconItem.count)
                        }
                    }
                }
            }
        }
    }
}

